def apply_transform(grid, dr=0, dc=2, dv=None):
    """Apply transformation: shift non-background cells by (dr, dc) and optionally change value"""
    result = [row[:] for row in grid]  # deep copy

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] not in [0, 8]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    val = grid[r][c]
                    if dv is not None:
                        result[nr][nc] = (val % 10 + dv) % 10
